  let(:activity) { create(:activity, points_possible: 100, activity_type: 'smart_book') }
  let(:attempt) do
    create(
      :attempt,
      activity: activity
    )
  end
  let(:statements) do
    submission['statements'].map do |statement_attrs|
      Xapi::Statement.new(statement_attrs)
    end
  end
  let(:responses) { described_class.new(statements) }
  let(:multiple_submission_statements) do
    mult_attempts_submission['statements'].map do |statement_attrs|
      Xapi::Statement.new(statement_attrs)
    end
  end

  # rubocop:enable Layout/SpaceInsideHashLiteralBraces,
  # rubocop:enable Style/StringLiterals, Layout/SpaceAroundOperators, Layout/LineLength

  describe '#answered' do
    it 'returns the responses that are answered' do
      expect(responses.answered.count).to be 5
    end
  end

  describe '#instructor_graded' do
    it 'returns the responses that are instructor-graded' do
      expect(responses.instructor_graded.count).to be 1
    end
  end

  describe 'when responses are retrieved' do
    it 'returns the responses sorted by question number' do
      expect(responses.answered.map(&:question_number)).to eq sorted_question_numbers
    end

    it 'returns only 1 response per subactivity for auto-graded responses' do
      expect(described_class.new(multiple_submission_statements).answered.count).to be 1
    end

    it 'returns only the latest response for multiple attempts on a subactivity' do
      responses = described_class.new(multiple_submission_statements)
      expect(responses.answered.first.submission_time).to eq(
        '2019-03-07T19:03:26Z'
      )
    end
  end

  context 'using different data setup' do
    let(:auto_graded_question_1_label) { 'a-g question 01' }
    let(:auto_graded_question_2_label) { 'a-g question 02' }
    let(:auto_graded_question_1_submission_1) do
      instance_double(
        Smartbook::Response,
        label: auto_graded_question_1_label,
        auto_graded?: true,
        instructor_gradable?: false,
        submission_time: Time.zone.now
      )
    end
    let(:auto_graded_question_2_submission_1) do
      instance_double(
        Smartbook::Response,
        label: auto_graded_question_2_label,
        auto_graded?: true,
        instructor_gradable?: false,
        submission_time: 1.hour.ago
      )
    end
    let(:auto_graded_question_2_submission_2) do
      instance_double(
        Smartbook::Response,
        label: auto_graded_question_2_label,
        auto_graded?: true,
        instructor_gradable?: false,
        submission_time: Time.now
      )
    end
    let(:auto_graded_question_2_submission_3) do
      instance_double(
        Smartbook::Response,
        label: auto_graded_question_2_label,
        auto_graded?: true,
        instructor_gradable?: false,
        submission_time: 2.hour.ago
      )
    end
    let(:instructor_graded_question_1_label) { 'i-g question 01' }
    let(:instructor_graded_question_2_label) { 'i-g question 02' }
    let(:instructor_graded_question_1_submission_1) do
      instance_double(
        Smartbook::Response,
        label: instructor_graded_question_1_label,
        auto_graded?: false,
        instructor_gradable?: true,
        submission_time: Time.now
      )
    end
    let(:instructor_graded_question_2_submission_1) do
      instance_double(
        Smartbook::Response,
        label: instructor_graded_question_2_label,
        auto_graded?: false,
        instructor_gradable?: true,
        submission_time: 1.hour.ago
      )
    end
    let(:instructor_graded_question_2_submission_2) do
      instance_double(
        Smartbook::Response,
        label: instructor_graded_question_2_label,
        auto_graded?: false,
        instructor_gradable?: true,
        submission_time: Time.now
      )
    end
    let(:instructor_graded_question_2_submission_3) do
      instance_double(
        Smartbook::Response,
        label: instructor_graded_question_2_label,
        auto_graded?: false,
        instructor_gradable?: true,
        submission_time: 2.hour.ago
      )
    end
    let(:answered) do
      [
        auto_graded_question_1_submission_1,
        instructor_graded_question_1_submission_1,
        auto_graded_question_2_submission_1,
        auto_graded_question_2_submission_2,
        instructor_graded_question_2_submission_1,
        auto_graded_question_2_submission_3,
        instructor_graded_question_2_submission_2,
        instructor_graded_question_2_submission_3
      ]
    end
    let(:responses) { described_class.new('statements': []) }

    before do
      allow(responses).to receive(:answered).and_return(answered)
    end

    describe '#answered' do
      it 'returns all the submitted responses' do
        expect(responses.answered).to eq(answered)
      end
    end

    describe '#answered_by_label' do
      it 'returns the submitted responses grouped by label' do
        expect(responses.answered_by_label).to eq(
          {auto_graded_question_1_label => auto_graded_question_1_submission_1,
          auto_graded_question_2_label => auto_graded_question_2_submission_3,
          instructor_graded_question_1_label => instructor_graded_question_1_submission_1,
          instructor_graded_question_2_label => instructor_graded_question_2_submission_3
          }
        )
      end
    end

    describe '#latest_auto_graded_responses' do
      it 'returns the latest response for each auto-graded question' do
        expect(responses.latest_auto_graded_responses).to eq(
          [auto_graded_question_1_submission_1, auto_graded_question_2_submission_2]
        )
      end
    end

    describe '#latest_instructor_graded_responses' do
      it 'returns the latest response for each instructor-graded question' do
        expect(responses.latest_instructor_graded_responses).to eq(
          [instructor_graded_question_1_submission_1, instructor_graded_question_2_submission_2]
        )
      end
    end

    describe '#auto_graded_by_label' do
      it 'returns the auto-graded responses grouped by label' do
        expect(responses.auto_graded_by_label).to eq(
          auto_graded_question_1_label => [
            auto_graded_question_1_submission_1
          ],
          auto_graded_question_2_label => [
            auto_graded_question_2_submission_1,
            auto_graded_question_2_submission_2,
            auto_graded_question_2_submission_3
          ]
        )
      end
    end

    describe '#instructor_graded_by_label' do
      it 'returns the instructor-graded responses grouped by label' do
        expect(responses.instructor_graded_by_label).to eq(
          instructor_graded_question_1_label => [
            instructor_graded_question_1_submission_1
          ],
          instructor_graded_question_2_label => [
            instructor_graded_question_2_submission_1,
            instructor_graded_question_2_submission_2,
            instructor_graded_question_2_submission_3
          ]
        )
      end
    end

    describe '#points_earned' do
      it 'returns the points earned for the question' do
        allow(auto_graded_question_1_submission_1).to receive(:points_earned)
          .and_return(33)
        expect(responses.points_earned(auto_graded_question_1_label)).to eq(33)
      end

      it 'returns 0 when the student did not submit anything for the question' do
        expect(responses.points_earned('question_with_no_submission')).to eq(0)
      end
    end
  end
